public class MaxHeap {
    int[] heap;
    int size;
    MaxHeap(int[] arr) {
        heap = arr.clone();
        size = arr.length;
        buildHeap();
    }
    void buildHeap() {
        for (int i = size/2 - 1; i >= 0; i--) heapify(i);
    }
    void heapify(int i) {
        int largest = i, l = 2*i+1, r = 2*i+2;
        if (l < size && heap[l] > heap[largest]) largest = l;
        if (r < size && heap[r] > heap[largest]) largest = r;
        if (largest != i) {
            int tmp = heap[i]; heap[i] = heap[largest]; heap[largest] = tmp;
            heapify(largest);
        }
    }
    public static void main(String[] args) {
        MaxHeap h = new MaxHeap(new int[]{3,1,6,5,2,4});
        for (int v : h.heap) System.out.print(v + " ");
    }
}

