#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
void heapify(vector<int>& h, int n, int i) {
    int lg=i, l=2*i+1, r=2*i+2;
    if (l<n&&h[l]>h[lg])lg=l;
    if (r<n&&h[r]>h[lg])lg=r;
    if (lg!=i) {
        swap(h[i], h[lg]);
        heapify(h, n, lg);
    }
}
void buildHeap(vector<int>& h) {
    int n=h.size();
    for (int i=n/2-1; i>=0; i--)heapify(h, n, i);
}
int main() {
    vector<int> a= {3, 1, 6, 5, 2, 4};
    buildHeap(a);
    for (int v:a)cout<<v<<" ";
    return 0;
}
